<main class="bb570-dashboard-page"><div class="bb570-shell"><section class="bb570-user-hero"><div><span>MY BLOOD DASHBOARD</span><h1>Welcome, <?=e($me['name'])?></h1><p>Your private donor activity, appointments and requests in one place.</p></div><div><a class="btn glass" href="/blood-request.php">＋ Request Blood</a><a class="btn primary" href="/blood-donate.php">♥ Donate</a></div></section><div class="bb570-user-kpis"><div><span>Donor status</span><b><?=e($data['donor']['donor_status']??'Not registered')?></b></div><div><span>Blood group</span><b><?=e($data['donor']['blood_group']??'—')?></b></div><div><span>Recorded donations</span><b><?=count($data['donations'])?></b></div><div><span>Appointments</span><b><?=count($data['appointments'])?></b></div><div><span>My requests</span><b><?=count($data['requests'])?></b></div></div><?php if(!$data['donor']):?><section class="bb570-empty action"><b>You are not registered as a donor yet.</b><span>Register once to book appointments and keep a donation history.</span><a class="btn primary" href="/blood-donate.php">Register as Donor</a></section><?php endif;?><section class="bb570-user-grid"><article class="bb570-user-panel"><div class="panel-head"><h2>Appointments</h2><a href="/blood-donate.php">Book new</a></div><?php if(!$data['appointments']):?><p class="muted">No appointments yet.</p><?php else:?><div class="bb570-list"><?php foreach($data['appointments'] as $a):?><div><b><?=e($a['bank_name'])?></b><span><?=e(date('d M Y · h:i A',strtotime($a['scheduled_at'])))?></span><em><?=e($a['status'])?></em></div><?php endforeach;?></div><?php endif;?></article><article class="bb570-user-panel"><div class="panel-head"><h2>Donation history</h2></div><?php if(!$data['donations']):?><p class="muted">No completed donation records yet.</p><?php else:?><div class="bb570-list"><?php foreach($data['donations'] as $d):?><div><b><?=e($d['bank_name'])?></b><span><?=e($d['blood_group'])?> · <?=e(date('d M Y',strtotime($d['collected_at'])))?></span><em><?=e($d['status'])?></em></div><?php endforeach;?></div><?php endif;?></article><article class="bb570-user-panel wide"><div class="panel-head"><h2>My blood requests</h2><a href="/blood-request.php">New request</a></div><?php if(!$data['requests']):?><p class="muted">No requests submitted.</p><?php else:?><div class="bb570-table-wrap"><table><thead><tr><th>Ref</th><th>Blood</th><th>Hospital</th><th>Need</th><th>Verification</th><th>Status</th></tr></thead><tbody><?php foreach($data['requests'] as $r):?><tr><td><?=e($r['request_no'])?></td><td><b><?=e($r['blood_group'])?></b></td><td><?=e($r['hospital_name'])?></td><td><?=(int)$r['units_needed']?> unit(s)</td><td><?=e($r['verification_status'])?></td><td><?=e($r['request_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article></section></div></main><?php bb570_public_footer(); ?>
